from collections import deque, defaultdict


def min_completion_time(n, time, relations):
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)
    for a, b in relations:
        graph[a].append(b)
        in_degree[b] += 1

    finish = [0] * (n + 1)
    queue = deque(v for v in range(1, n + 1) if in_degree[v] == 0)
    processed = 0
    while queue:
        u = queue.popleft()
        processed += 1
        finish[u] += time[u - 1]
        for w in graph[u]:
            if finish[u] > finish[w]:
                finish[w] = finish[u]
            in_degree[w] -= 1
            if in_degree[w] == 0:
                queue.append(w)

    if processed != n:
        return -1
    return max(finish[1:])
